<script module lang="ts">
/**
 * Inline status callout (`design/components/alert.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/alert.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { onDestroy, type Snippet } from 'svelte'

import { Icon, agentMember, joinSlot, useDeparture, watchEffect } from '@polymorph/svelte'
import styles from '@polymorph/recipes/structure/alert.module.css'
import Button from '../controls/Button.svelte'

export type AlertTone = NonNullable<AlertProps['tone']>

export interface AlertProps {
  /**
   * The first action: one `ghost`/`soft` `sm` Button, such as Apply.
   */
  action?: Snippet
  /**
   * The body copy. With no title and no content the Alert renders nothing.
   */
  children?: Snippet
  /**
   * The ✕'s accessible name, default `Dismiss`; localized hosts pass their own.
   */
  dismissLabel?: string
  /**
   * `false` hides the tone glyph, for dense stacks where the wash already shows the tone.
   */
  icon?: false
  /**
   * Renders the ✕, and is called after the row has closed so the app can unmount it.
   */
  onDismiss?: () => void
  /**
   * The second action: one `ghost` `sm` Button after `action`, such as Discard. Two is the most
   * an Alert takes; content that needs more is a Card.
   */
  secondaryAction?: Snippet
  /**
   * The first line. An empty title counts as no title.
   */
  title?: string
  tone?: 'info' | 'warning' | 'success' | 'danger'
}
</script>

<script lang="ts">
let {
  action,
  children,
  dismissLabel = 'Dismiss',
  icon = undefined,
  onDismiss,
  secondaryAction,
  title,
  tone = 'info',
}: AlertProps = $props()
const joined = joinSlot(undefined, () => ({}))
const listening = {
  get dismiss() {
    return onDismiss !== undefined
  },
}
const slots = {
  get action() {
    return action
  },
  get default() {
    return children
  },
  get secondaryAction() {
    return secondaryAction
  },
}
let settle = $state(undefined as (() => void) | undefined)
let closeRegion = $state<HTMLElement | null>(null)
let root = $state<HTMLElement | null>(null)
const departure = useDeparture(() => root, 'alert.dismiss')
let release1: (() => void) | undefined
const effect1 = () => {
  release1?.()
  undefined
  release1 = () => {
    settle?.()
  }
}
watchEffect(effect1)
onDestroy(() => release1?.())
let release2: (() => void) | undefined
const effect2 = () => {
  release2?.()
  const ran = agentMember({
    member: 'Alert',
    element: () => root,
    state: () => ({ tone: tone, title: title ?? '', dismissible: listening.dismiss }),
    actions: {
      dismiss: () =>
        (() => {
          if (!listening.dismiss) throw new Error('This alert has no dismiss control.')
          return new Promise<void>((resolve) => {
            settle = () => {
              settle = undefined
              resolve()
            }
            departure.start(() => {
              onDismiss?.()
              settle?.()
            })
          })
        })(),
    },
    withholds: () => closeRegion,
  })
  release2 = () => {
    ran()
  }
}
watchEffect(effect2)
onDestroy(() => release2?.())
</script>

{@render joined.start?.()
}{#if joined.shown
  }{#if (title !== undefined && title !== '') || slots.default
    }<div
      bind:this={root}
      class={styles.alert}
      role={tone === 'warning' || tone === 'danger' ? 'alert' : 'status'}
      data-tone={tone}
      data-state={(departure.active) ? 'closed' : undefined}
      data-member="alert"
      ><div class={styles.panel}
        >{#if icon !== false
          }<span class={styles.glyph}><Icon name={tone === 'danger' ? 'error' : tone} /></span
        >{/if
        }<div class={styles.body}
          >{#if title !== undefined && title !== ''}<p class={styles.title}>{title}</p>{/if
          }{#if slots.default}<div class={styles.text}>{@render children?.()}</div>{/if
          }{#if slots.action || slots.secondaryAction
            }<div class={styles.action}>{@render action?.()}{@render secondaryAction?.()}</div
          >{/if
        }</div
        >{#if listening.dismiss
          }<div bind:this={closeRegion} class={styles.close}
            ><Button
              variant="ghost"
              tone="neutral"
              size="sm"
              iconOnly={true}
              icon="close"
              label={dismissLabel}
              onClick={() => { departure.start(() => { onDismiss?.(); settle?.() }) }}
          /></div
        >{/if
      }</div
    ></div
  >{/if
}{/if
}{@render joined.end?.()}
